def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>These patent drawings cover trapping and fishing gear: a slatted stream fish trap, an ice-fishing tip-up, a net-maker's needle, a live box trap, a spring hook that sets itself, a weedless hook, the snap trap that protects stored food from rats and mice, and a large commercial trap-net. All are expired and free to copy. As section 1.1 says, trapping and fishing laws apply until the law itself has gone. Many of these devices (set lines, fish traps, trap-nets) are restricted or banned in normal times.</p>"
UNPATENTED = ["The snares, figure-4 and Paiute deadfalls, gorges, stakeout lines and gill nets in Parts 2&ndash;4 are traditional methods that anyone may use."]
PATENTS = [
P("US22644","c4/76/02/96210625178a23/US22644.pdf","23/b2/f7/c1bcf66cf7214c/US22644-drawings-page-1.png","A","1859-01-18","Robert Gray (Anson, Maine)","Fish-trap",
  "A timber-framed trap for catching fish in streams. It has ground sills, posts and top beams, fixed slats, a throat with springs and swinging (&ldquo;vibrating&rdquo;) slats, a covered holding chamber and a removable strainer. It can be built from poles and split slats (see section 4.4).","Fig. 1 perspective of trap; Fig. 2 section of throat; Fig. 3 strainer"),
P("US434426","5a/76/a2/c261bbfee36013/US434426.pdf","b3/39/b7/9b6607e7875e2c/US434426-drawings-page-1.png","A","1890-08-19","Charles Wesley Costellow (Waterborough, Maine)","Tip-up for fishing",
  "An ice-fishing tip-up: a notched standard holding a tipping flag-staff on a pin, with a flag of bright cloth that signals a bite. The line is wound on notches at the ends. Costellow says the aim of such tackle is to let one or two people set and tend twenty-five or fifty lines at once. You can make one from two sticks, a nail and a rag.","Tip-up set over the hole and sprung"),
P("US579157","93/b5/2e/ffbe5705891b29/US579157.pdf","1a/a5/40/28f81000405774/US579157-drawings-page-1.png","A","1897-03-23","William J. May (Homosassa, Florida)","Seine-needle",
  "A needle for making and mending fishing nets, seines and hammocks, with a small cutting blade that folds into the body. The outline is the standard netting needle: carve it from hardwood or bone to knit the gill net in section 4.3.","Needle with blade housed and extended"),
P("US3326","08/30/04/aeeb0d9a3e3d66/US3326.pdf","ef/6a/87/61486b5344a3dd/US3326-drawings-page-1.png","B","1843-11-06","Jacob Stroop &amp; John Esthall (Allegheny, Pennsylvania)","Box-trap for catching animals",
  "A live-catch box trap. An animal steps on a treadle in the entrance, which releases a turnstile of bars (held by a ratchet and clicks). The turning bars push the animal into a cage compartment. A wooden box trap that takes animals alive.","Fig. 1 trap with turnstile, spool and treadle; Fig. 2 plan"),
P("US283444","d5/45/9e/729151540cd1ec/US283444.pdf","91/eb/58/82b400c677d1d5/US283444-drawings-page-1.png","B","1883-08-21","Richmond A. Wentworth (Appleton, Maine)","Fish-trap or spring-hook",
  "A spring attachment for a fishing line. When a fish pulls the bait, a trigger releases the spring, which jerks the hook into the fish's mouth. Fit one to the stakeout lines in section 4.2 so the hook sets itself.","Fig. 1 set; Fig. 2 sprung; Fig. 3 section of trigger"),
P("US549842","2b/bf/b5/f3491cf17f18de/US549842.pdf","bf/c0/e1/6601d072d03a18/US549842-drawings-page-1.png","B","1895-11-12","Wheeler Cable (Boston, Massachusetts)","Fish-hook",
  "A weedless hook. The curved body is weighted on its back, opposite the point, and a coloured feather is bound on as an attractor. Cable wrote that it would not catch in eel-grass or lily pads and was meant to hook the fish in the upper jaw, which is strong enough to hold it.","Hook side views showing weighted back and feather"),
P("US528671","b3/3c/1f/b67fa8b1210eab/US528671.pdf","22/b0/4a/798ba649236328/US528671-drawings-page-1.png","C","1894-11-06","William C. Hooker (Abingdon, Illinois)","Animal-trap",
  "The flat spring snap trap for mice and rats. It is simple and cheap, set close to a rat hole so an animal crossing it springs it even when it is not after the bait, and so sensitive it fires at the slightest touch to the bait. Use it to protect stored food. It needs spring wire and a factory to make in numbers.","Trap set and sprung, with spring, bail and trigger"),
P("US644459","84/a1/10/4e01c3c51f28ce/US644459.pdf","0a/b9/ce/a20c8dfdaa5ae4/US644459-drawings-page-1.png","C","1900-02-27","Thomas Redding (Seattle, Washington)","Fish trap-net",
  "A large V-shaped trap-net with tapering netted walls and partitions. It can be towed by boats or anchored and held up by floats. This is a commercial net, restricted in most waters.","Plan and elevation of the V-shaped net and compartments"),
P("US599086","52/80/65/db00b31392035a/US599086.pdf","75/21/27/0dd6a57e8c8271/US599086-drawings-page-1.png","A","1898-02-15","Charles H. Wisner","Minnow-trap",
  "A minnow trap: a solid, transparent box or cylinder with funnel-shaped openings that point inward. Minnows swim in through the funnels to reach bait inside (finely chopped meat, crushed bread or cracker crumbs) and cannot find the narrow way out. The patent explains that the walls must be solid so the bait stays put, and transparent so the minnows can see it. Minnows are bait for bigger fish. Check local rules (see the legal note in this guide).","Fig. 1 the trap; sections through the funnel ends"),
P("US318190","fe/a8/d8/b33f5744835b87/US318190.pdf","1d/34/4d/395cd3390ef415/US318190-drawings-page-1.png","B","1885-05-19","John Kopf","Fishing-reel",
  "A geared (multiplying) casting reel whose spool can be thrown out of gear from the handle. When casting, the spinning handle then does not keep paying out line after the bait lands, which is what makes a reel 'overrun' and tangle. A lever carrying the handle gear is moved by a throw-off button on the reel's cap.","Sheet 1: the reel, spool pinion, lever and throw-off"),
P("US154228","54/eb/4c/72d7dbf51d8fc3/US154228.pdf","pdf:1","C","1874-08-18","John W. Court & Chauncey O. Crosby","Machine for making fish-hooks",
  "A factory machine that makes fish-hooks from a continuous coil of wire. The wire is fed forward one hook-length at a time. Dies flatten the end to start the point, a cutter cuts the barb, and the piece is cut off. Trimming dies shape the point, and a 'ringer' forms the eye ring. For hooks made by hand from pins, wire or nails, see 4.1 Hooks and gorges.","Sheet 1: the machine; later sheets show the dies, barb cutter and ringer"),
]
